}
vec4 frag () {
  vec4 source = sampleSource(uv0);
  float time = cc_time.x;
  float waveFront = clamp(
    progress + waveAmplitude * sin(waveFrequency * uv0.y + time * waveSpeed),
    -waveAmplitude,
    1.0 + waveAmplitude
  );
  float body = step(uv0.x, waveFront);
  float edge = (1.0 - step(max(0.001, edgeWidth), abs(uv0.x - waveFront))) * body;
  float particles = 0.0;
